CREATE OR REPLACE FUNCTION <schema>.lifecycle_witness_bind_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO '<schema>', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actual_owner uuid;
BEGIN
  IF TG_OP='UPDATE' THEN SELECT tenant_id INTO actual_owner FROM record WHERE id=OLD.id; ELSE actual_owner := coalesce(NEW.account_id,NEW.plant_id, '00000000-0000-0000-0000-000000000000'::uuid); END IF;

  IF TG_OP='UPDATE' AND NEW.id <> OLD.id THEN RAISE EXCEPTION 'immutable_record_id' USING ERRCODE='23514'; END IF;
  INSERT INTO record(id,kind,tenant_id) VALUES (NEW.id,'lifecycle_witness',actual_owner) ON CONFLICT DO NOTHING;
