CREATE OR REPLACE FUNCTION <schema>.settings_update_name(handle uuid, new_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO '<schema>', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE subject uuid;
BEGIN
 SELECT a.id INTO subject FROM auth_session s JOIN account a ON a.auth_user_id=s.user_id WHERE s.id=handle AND s.expires_at>clock_timestamp() FOR UPDATE OF a;
 IF subject IS NULL OR length(btrim(new_name)) NOT BETWEEN 1 AND 200 OR EXISTS(SELECT FROM lifecycle_witness WHERE kind='account' AND opaque_subject_id=subject AND state NOT IN ('active','cancelled')) THEN RAISE EXCEPTION 'unavailable' USING ERRCODE='42501'; END IF;
 UPDATE auth_user SET name=btrim(new_name),updated_at=clock_timestamp() WHERE id=(SELECT auth_user_id FROM account WHERE id=subject);
END $function$

CREATE OR REPLACE FUNCTION <schema>.purge_document_revisions(subject uuid, request uuid, expected bigint, document_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO '<schema>', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE affected bigint;
BEGIN
  PERFORM 1 FROM lifecycle_witness w WHERE w.opaque_subject_id=subject AND w.request_id=request
    AND w.request_revision=expected AND w.kind IN ('account','plant')
    AND w.state='purging' AND w.cancel_until<=clock_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unavailable' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM document d WHERE d.id=document_id AND d.tenant_id=subject FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unavailable' USING ERRCODE='42501'; END IF;
  -- Provenance-only source links are detached by the lifecycle producer before
  -- this step; FK references refuse incomplete sequencing, never CASCADE it.
  UPDATE document SET current_revision_id=NULL WHERE id=document_id AND tenant_id=subject;
  DELETE FROM document_revision r WHERE r.document_id=purge_document_revisions.document_id AND r.tenant_id=subject;
  GET DIAGNOSTICS affected=ROW_COUNT;
  RETURN affected;
END $function$

CREATE OR REPLACE FUNCTION <schema>.scrub_people_account_author(subject uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO '<schema>', 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
 PERFORM 1 FROM lifecycle_witness WHERE account_id=subject AND state IN ('purging','purged') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'account_purge_witness_required' USING ERRCODE='23514'; END IF;
 UPDATE person_note SET author_id=NULL WHERE author_id=subject;
 UPDATE audit_event SET actor_token=coalesce(actor_token,encode(sha256(convert_to(tenant_id::text||'/'||subject::text,'UTF8')),'hex')),actor_id=NULL WHERE actor_id=subject;
 UPDATE audit_event SET before_value=before_value-'linked_account_id' WHERE before_value->>'linked_account_id'=subject::text;
 UPDATE audit_event SET after_value=after_value-'linked_account_id' WHERE after_value->>'linked_account_id'=subject::text;
END $function$

CREATE OR REPLACE FUNCTION <schema>.settings_purge_content(witness uuid, request uuid, expected bigint)
 RETURNS void
